use vstd::prelude::*;

verus! {

fn remove_kth_element(list: &Vec<i32>, k: usize) -> (new_list: Vec<i32>)
    requires
        list.len() > 0,
        1 <= k < list.len(),
    ensures
        new_list.len() == list.len() - 1,
        forall|i: int| 0 <= i < k - 1 ==> new_list[i] == list[i],
        forall|i: int| k - 1 <= i < new_list.len() ==> new_list[i] == list[i + 1],
{
    let mut result = Vec::new();
    let mut idx: usize = 0;
    
    while idx < list.len()
        invariant
            idx <= list.len(),
            1 <= k < list.len(),
            result.len() == if idx <= k - 1 { idx } else { idx - 1 },
            forall|i: int| 0 <= i < idx && i < k - 1 ==> result[i] == list[i],
            forall|i: int| k <= i < idx ==> result[i - 1] == list[i],
    {
        if idx != k - 1 {
            result.push(list[idx]);
        }
        idx = idx + 1;
    }
    
    result
}

}

